(5930758, 864955, 74911, '<td valign="top">Nice backlighting. Clever shot.</td>', 'Nice backlighting. Clever shot.', '2010-04-05 01:06:45.000000', NULL, 1),
(5930762, 863881, 74911, '<td valign="top">Brilliant efforts. Good results.</td>', 'Brilliant efforts. Good results.', '2010-04-05 01:07:15.000000', NULL, 1),
(5930764, 864590, 96751, '<td valign="top">Very interesting bugs.  Love their color and shape, but not crazy about the murky green background.</td>', 'Very interesting bugs.  Love their color and shape, but not crazy about the murky green background.', '2010-04-05 01:07:55.000000', NULL, 1),
(5930765, 864795, 74911, '<td valign="top">Setup is good. The lighting and its reflections on the glass does not work for these kinda shots for me.</td>', 'Setup is good. The lighting and its reflections on the glass does not work for these kinda shots for me.', '2010-04-05 01:07:57.000000', NULL, 1),
(5930769, 864805, 96751, '<td valign="top">Wonderful architectural abstract.  I think the flags weaken the "three" but the colors and textures are nice and sharp.</td>', 'Wonderful architectural abstract.  I think the flags weaken the "three" but the colors and textures are nice and sharp.', '2010-04-05 01:08:40.000000', NULL, 1),
(5930770, 864698, 49954, '<td valign="top">Really great photo, but sadly I feel it DNMC because the frontmost rider appears as the main subject and the other two are simply supporting characters in the story.</td>', 'Really great photo, but sadly I feel it DNMC because the frontmost rider appears as the main subject and the other two are simply supporting characters in the story.', '2010-04-05 01:09:00.000000', NULL, 1),
(5930771, 865181, 96751, '<td valign="top">Not crazy about the color.  Very interesting (if icky) subjects.</td>', 'Not crazy about the color.  Very interesting (if icky) subjects.', '2010-04-05 01:09:14.000000', NULL, 1),
(5930781, 864828, 96751, '<td valign="top">Nice shapes.  It''s clearly a race, but they seem oddly static.  Wish there''d been a bit more splash against the hulls to convey speed.</td>', 'Nice shapes.  It''s clearly a race, but they seem oddly static.  Wish there''d been a bit more splash against the hulls to convey speed.', '2010-04-05 01:09:54.000000', NULL, 1),
