(5937647, 864943, 91496, '<td valign="top">I really like the way the 3 tulips arch in unison.  All of the greens set of the read nicely.  bAckdrop of course makes the 3 subject stand out perfectly</td>', 'I really like the way the 3 tulips arch in unison.  All of the greens set of the read nicely.  bAckdrop of course makes the 3 subject stand out perfectly', '2010-04-08 16:47:44.000000', NULL, 1),
(5937649, 865179, 91496, '<td valign="top">Very nice with the softness and use of DOF.  I like the arrangement and composition.  The white backdrop while blown out works very well here.</td>', 'Very nice with the softness and use of DOF.  I like the arrangement and composition.  The white backdrop while blown out works very well here.', '2010-04-08 16:48:45.000000', NULL, 1),
(5937651, 865137, 91496, '<td valign="top">Very nice.  Alsmost look like 3 photos superimposed on each other which is a nice effect to pull off in one image. The ripples and relections are facinating.</td>', 'Very nice.  Alsmost look like 3 photos superimposed on each other which is a nice effect to pull off in one image. The ripples and relections are facinating.', '2010-04-08 16:49:51.000000', NULL, 1),
(5937652, 864795, 91496, '<td valign="top">Somewhat a stock shot, but the added twist of the offset stacking really adds to teh impact.  Well done.  Lighting is great.</td>', 'Somewhat a stock shot, but the added twist of the offset stacking really adds to teh impact.  Well done.  Lighting is great.', '2010-04-08 16:50:48.000000', NULL, 1),
(5937656, 865175, 91496, '<td valign="top">I love all the textures here.  The lighitng is great creating nice interplay of light and dark.</td>', 'I love all the textures here.  The lighitng is great creating nice interplay of light and dark.', '2010-04-08 16:51:38.000000', NULL, 1),
(5937668, 864971, 101668, '<td valign="top">Not equal clarity on this one.</td>', 'Not equal clarity on this one.', '2010-04-08 16:55:37.000000', NULL, 1),
