(5939891, 864916, 83313, '<td valign="top">Very nice shot, but what is there 3 of in this scene?</td>', 'Very nice shot, but what is there 3 of in this scene?', '2010-04-11 02:06:59.000000', NULL, 1),
(5939892, 864740, 83313, '<td valign="top">Not pleasant to look at. Softer lighting could have helped perhaps.</td>', 'Not pleasant to look at. Softer lighting could have helped perhaps.', '2010-04-11 02:08:04.000000', NULL, 1),
